"""Render Frisco county and neighborhood guides from maintained local content."""
from pathlib import Path
from html import escape
import json,re
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'assets/frisco-local-content.json').read_text())
base=(R/'frisco-pool-service/index.html').read_text()
header=base[base.index('<body>')+6:base.index('<main')]
footer=base[base.index('<footer'):base.index('</body>')]
# Frisco guides remain reachable from every pool footer.
if 'href="/frisco-neighborhoods/"' not in footer:
 footer=footer.replace('<nav aria-label="Footer planning">','<nav aria-label="Footer planning"><a href="/frisco-neighborhoods/">Frisco neighborhoods &amp; counties</a>')
S={x['slug']:x['name'] for f in ['pool-services-content.json','pool-cleaning-content.json'] for x in json.loads((R/'assets'/f).read_text())}
SOURCE_WATER='https://www.friscotexas.gov/525/Residents'
SOURCE_PERMIT='https://www.friscotexas.gov/211/Pools-Pool-Enclosures'
def link(slug,label):return '<a href="'+('/'+slug+'/' if slug else '/')+'">'+escape(label)+'</a>'
def cards(items,search=False):
 out=''
 for d in items:
  attr=f' data-frisco-guide data-kind="{d["kind"]}" data-search="{escape(d["name"]+" "+d["focus"]+" "+d["summary"]+" "+" ".join(q for q,_,_ in d["questions"])+" "+" ".join(S[x] for x in d["services"]),quote=True)}"' if search else ''
  out+=f'<article class="local-card"{attr}><span class="eyebrow">{d["kind"]} guide · Frisco</span><h3>{escape(d["name"])}</h3><p>{escape(d["focus"])}</p>{link(d["slug"],"Explore this pool-care guide")}</article>'
 return out

def head(title,desc,route,image,schemas):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'<title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{route}"><meta name="theme-color" content="#123f53"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="/assets/pool-photos/{image}"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">'+''.join(f'<link rel="stylesheet" href="/assets/{f}">' for f in ['pool-base.css','navigation.css','pool-services.css','frisco-local.css','typography.css'])+'<link rel="icon" href="/assets/frisco-pool-icon.svg" type="image/svg+xml">'+''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schemas)+'</head><body>'+header

def breadcrumb(items):return '<nav class="local-breadcrumb" aria-label="Breadcrumb">'+''.join(link(slug,label)+'<span aria-hidden="true">/</span>' for slug,label in items)+'</nav>'
def crumbs_schema(route,name):return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'/'},{'@type':'ListItem','position':2,'name':'Frisco neighborhoods','item':'/frisco-neighborhoods/'},{'@type':'ListItem','position':3,'name':name,'item':route}]}
def service_schema(d,route):return {'@context':'https://schema.org','@type':'Service','name':'Pool service — '+d['name'],'description':d['summary'],'serviceType':['Pool cleaning','Pool equipment repair','Pool leak assessment'],'provider':{'@type':'Organization','name':'Frisco Pool Services','url':'/','telephone':'+1-945-777-3345','logo':'/assets/frisco-pool-logo.svg'},'areaServed':{'@type':'Place','name':d['name']+', Frisco, Texas','containedInPlace':{'@type':'City','name':'Frisco'}},'url':route,'image':'/assets/pool-photos/'+d['image']}
def hero(title,desc,image,focus):return f'<div class="local-hero"><div><span class="eyebrow">FRISCO POOL SERVICES · LOCAL CARE GUIDES</span><h1>{escape(title)}</h1><p>{escape(desc)}</p><div class="local-actions"><a class="btn" href="tel:+19457773345">Call 945-777-3345</a><a class="btn gold" href="#questions">Explore pool problems</a></div></div><figure><img src="/assets/pool-photos/{image}" alt="'+({'pool-08.webp':'Backyard pool with green water','pool-02.webp':'Pool filter equipment being cleaned','pool-16.webp':'Pool waterline tile before and after cleaning','pool-06.webp':'Salt chlorine generator component','pool-26.webp':'Pool heating equipment beside a wall','pool-21.webp':'Pool filtration equipment at an equipment pad','pool-20.webp':'Pump and filter at a pool equipment pad','pool-24.webp':'Pool inspection using listening equipment'}.get(image,'Backyard swimming pool and surrounding patio'))+f'" width="1200" height="900" fetchpriority="high"><figcaption>Guide focus: {escape(focus)}. Pool and equipment imagery illustrates the service topic.</figcaption></figure></div>'
def cta():return '<section class="final-cta"><span class="eyebrow">FRISCO POOL SERVICES</span><h2>Start with your pool.<br>Leave with a clearer plan.</h2><p>Share your address, what changed, and the equipment involved.<br>Confirm coverage, scope, pricing, and availability directly with the team.</p><a class="btn" href="tel:+19457773345">Call 945-777-3345</a></section>'
for i,d in enumerate(D):
 route='/'+d['slug']+'/'
 short=d['name'].replace(' side of Frisco','')
 title=('Pool Service in Frisco — '+short if d['kind']=='County' else 'Pool Service in '+d['name']+', Frisco')
 schemas=[service_schema(d,route),crumbs_schema(route,d['name']),{'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a,_ in d['questions']]}]
 s=head(title+' | Frisco Pool Services',d['summary'],route,d['image'],schemas)+breadcrumb([('','Home'),('frisco-pool-service','Frisco pool service'),('frisco-neighborhoods','Local guides')])+'<main id="main">'
 s+=hero(title,d['summary'],d['image'],d['focus'])
 s+='<section class="local-section local-intro"><div><div><span class="eyebrow">THE PROPERTY SHAPES THE PLAN</span><h2>What matters at your pool?</h2></div><div><p>'+escape(d['context'])+'</p><p>These are inspection and planning questions, not a claim that a particular fault affects every home in '+escape(d['name'])+'. The pool’s condition, equipment, and service history determine the work.</p></div></div></section>'
 s+='<section class="local-section local-layout" id="questions"><div>'
 for j,(q,a,slug) in enumerate(d['questions'],1):s+=f'<article class="local-answer" id="question-{j}"><h2>{escape(q)}</h2><p>{escape(a)}</p><p class="local-related">Explore the scope: {link(slug,S[slug])}</p></article>'
 s+='</div><aside class="local-toc"><span class="eyebrow">START WITH A QUESTION</span><h2>Find your next step</h2><nav aria-label="Questions on this page">'+''.join(f'<a href="#question-{j}">{escape(q)}</a>' for j,(q,_,_) in enumerate(d['questions'],1))+'</nav><a class="btn" href="#visit">Plan the service visit</a><p>For private backyard pools. Confirm your address and requested work before scheduling.</p></aside></section>'
 s+='<section class="local-section" id="visit"><span class="eyebrow">FROM OBSERVATION TO AN AGREED SCOPE</span><h2>What should the visit cover?</h2><ol class="local-steps">'+''.join('<li>'+escape(x)+'</li>' for x in d['visit'])+'</ol><div class="local-brief"><div><h3>What should I have ready?</h3><ul>'+''.join('<li>'+escape(x)+'</li>' for x in d['brief'])+'</ul></div><div><h3>Can photos help?</h3><p>Start with the whole pool, the affected area, and readable equipment labels. Choose photos without people. Our on-device checker rejects detected faces and offers preliminary visible water-color observations and inspection prompts; it cannot find hidden faults.</p><div class="local-actions"><a class="btn" href="/pool-checker/">Open the pool photo checker</a></div></div></div>'
 s+='<p class="local-reference">Local setting: <a href="'+d['source']+'">'+('Frisco Chamber county information' if d['kind']=='County' else escape(d['name'])+' community information')+'</a>. For work involving water discharge or alterations, consult <a href="'+SOURCE_WATER+'">Frisco’s stormwater and pool-maintenance guidance</a> and <a href="'+SOURCE_PERMIT+'">city pool and enclosure information</a>. Confirm requirements for the actual property and proposed work.</p></section>'
 s+='<section class="local-section" id="services"><span class="eyebrow">MATCH THE WORK TO THE CONDITION</span><h2>Which service fits the problem?</h2><div class="local-service-links">'+''.join(link(x,S[x]) for x in d['services'])+'</div><div class="local-bridge"><h3>Looking beyond this guide?</h3><p>Return to the '+link('frisco-pool-service','main Frisco pool service guide')+' or compare '+link('frisco-neighborhoods','Frisco county and neighborhood guides')+'. Broader city coverage stays in our '+link('service-areas','service-area directory')+'.</p></div></section>'
 related=[D[(i+1)%len(D)],D[(i+2)%len(D)]]
 s+='<section class="local-section"><h2>Explore more Frisco pool-care questions</h2><div class="local-grid local-county-grid">'+cards(related)+'</div></section>'+cta()+'</main>'+footer+'</body></html>'
 out=R/d['slug']/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(s)
# A searchable directory gives visitors one useful entry point into all local guides.
route='/frisco-neighborhoods/'
schemas=[{'@context':'https://schema.org','@type':'CollectionPage','name':'Frisco neighborhood and county pool service guides','url':route,'hasPart':[{'@type':'WebPage','name':x['name']+' pool service','url':'/'+x['slug']+'/'} for x in D]}]
s=head('Frisco Neighborhood & County Pool Service Guides | Frisco Pool Services','Explore private pool care across Frisco’s Collin and Denton County portions and eight communities. Find local guides by neighborhood or pool problem.',route,'pool-10.webp',schemas)+breadcrumb([('','Home'),('frisco-pool-service','Frisco pool service')])+'<main id="main">'
s+=hero('Frisco pool care. Find your corner.','Two counties. Different backyards. Start with your neighborhood, then explore the pool problem and the work worth discussing.','pool-10.webp','County and neighborhood guides for private pools')
s+='<section class="local-section local-intro" id="questions"><div><div><span class="eyebrow">ONE CITY, TWO COUNTIES</span><h2>Which part of Frisco is covered?</h2></div><div><p>Frisco spans Collin and Denton counties. Our county guides address the Frisco portions, rather than promising service throughout either county. Neighborhood pages go a level deeper into useful pool-care planning: debris and circulation, salt-system alerts, pool/spa controls, water loss, or finish care.</p><p>Use your property address to confirm coverage. A community name does not establish the condition of your pool, and county lines do not diagnose water chemistry, equipment failure, or a leak.</p><p class="local-reference">Geography reference: <a href="https://friscochamber.com/about-frisco/">Frisco Chamber of Commerce’s city profile</a>. Neighborhood context comes from the community, developer, or official visitor information linked in each guide.</p></div></div></section>'
s+='<section class="local-section" id="guides"><span class="eyebrow">FIND A USEFUL STARTING POINT</span><h2>Where is your pool?</h2><p>Search a community or a concern such as salt, filter, water loss, or stains. These are property-planning guides, not neighborhood-wide fault statistics.</p><div class="local-filters"><label for="friscoSearch">Neighborhood or pool problem<input id="friscoSearch" type="search" placeholder="Try Starwood, salt, or water loss"></label><label for="friscoKind">Guide type<select id="friscoKind"><option value="all">All local guides</option><option value="County">County guides</option><option value="Neighborhood">Neighborhood guides</option></select></label><button class="btn gold" id="friscoReset" type="button">Clear filters</button></div><p id="friscoCount" class="local-count" role="status" aria-live="polite">10 Frisco guides</p><div class="local-grid">'+cards(D,True)+'</div><p id="friscoEmpty" hidden>No matching guide. Clear the filters or call us with your property address.</p><noscript><p>Search filters require JavaScript. Every guide remains available in the list above.</p></noscript></section>'
s+='<section class="local-section" id="visit"><h2>What if my neighborhood is not listed?</h2><p>Start with the '+link('frisco-pool-service','citywide Frisco pool service guide')+' and share your address. This directory is a set of detailed guides, not a boundary map or an exhaustive list of Frisco subdivisions. Confirm availability for your property and the requested work directly.</p><div class="local-brief"><div><h3>How do I choose the service?</h3><p>Recurring upkeep belongs in '+link('weekly-service','weekly pool care')+'. A neglected pool may need '+link('green-pool-cleaning','green-pool recovery')+' or '+link('one-time-pool-cleaning','a one-time cleanup')+'. Weak flow, changing water levels, and repeated equipment alerts may need diagnostics alongside cleaning.</p></div><div><h3>Can I start with a photo?</h3><p>The '+link('pool-checker','pool photo checker')+' can organize visible color clues and symptom-based inspection areas. It runs on your device and rejects photos with detected faces. It cannot confirm chemistry, identify hidden leaks, or replace equipment testing.</p></div></div><div class="local-actions"><a class="btn" href="tel:+19457773345">Discuss your Frisco pool</a><a class="btn gold" href="/service-areas/">View broader service areas</a></div></section>'+cta()+'</main>'+footer+'<script src="/assets/frisco-local.js" defer></script></body></html>'
(R/'frisco-neighborhoods').mkdir(exist_ok=True);(R/'frisco-neighborhoods/index.html').write_text(s)
print('Rendered 10 local guides and searchable Frisco directory.')
